Definition div3n2n_word_builder n {term : Alg.Core.Algebra}
    (rec : term (Ty.Prod (Word (S n)) (Word n)) (Word (S n))) :
  term (Ty.Prod (Ty.Prod (Word (S n)) (Word n)) (Word (S n)))
       (Ty.Prod (Word n) (Word (S n))) :=
  (((O O H &&& I O H) >>> @div3n2n_approx_spec n term rec) &&& (O I H &&& I H)) >>>
    @div3n2n_body_spec n term.

Definition subtract_word_spec {term : Alg.Core.Algebra} (n : nat) :
    @Alg.Core.domain term (Ty.Prod (Word n) (Word n)) (Ty.Prod Bit (Word n)) :=
  AC.comp (AC.pair Bit.false AC.iden) (@full_subtract_word_spec term n).

Definition decrement_word_spec {term : Alg.Core.Algebra} (n : nat) :
    @Alg.Core.domain term (Word n) (Ty.Prod Bit (Word n)) :=
  AC.comp (AC.pair Bit.true AC.iden) (@full_decrement_word_spec term n).

Definition lt_word_spec {term : Alg.Core.Algebra} n :
    @Alg.Core.domain term (Ty.Prod (Word n) (Word n)) Bit :=
  AC.comp (@subtract_word_spec term n) (AC.take AC.iden).
